package com.medcore.backend.api.enfermeria;import java.time.*;public record ObservacionResponse(Long id,Long internacionId,Long enfermeroId,LocalDateTime fechaHora,String descripcion,TipoObservacion tipo,String autor){public static ObservacionResponse from(Observacion o){return new ObservacionResponse(o.getId(),o.getInternacionId(),o.getEnfermeroId(),o.getFechaHora(),o.getDescripcion(),o.getTipo(),o.getAutor());}}
